function buildCommand() {
  const __args = [['gamble'], 'Economy', 'Gamble your money for a chance to double it', async ({ sock, from, msg, args, senderNumber, db }) => {
  const amt = parseInt(args[0], 10);
  const e = db.econ(senderNumber);
  if (!amt || amt <= 0 || amt > e.balance) return sock.sendMessage(from, { text: 'Invalid bet amount.' }, { quoted: msg });
  const win = Math.random() < 0.45;
  e.balance += win ? amt : -amt;
  db.saveEcon();
  await sock.sendMessage(from, { text: win ? `🎉 You won! +${amt}. Wallet: ${e.balance}` : `💸 You lost ${amt}. Wallet: ${e.balance}` }, { quoted: msg });
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
